$scratch = Join-Path ([IO.Path]::GetTempPath()) ('dcoir-608-native-meta-' + [guid]::NewGuid().ToString('N'))
$owned = $false
$links = [System.Collections.Generic.List[object]]::new()
$passed = 0
function New-OwnedAlias([string]$Kind,[string]$Link,[string]$Target) {
    $directory = $Kind -in @('Junction','DirectorySymbolicLink')
    $links.Add(@{ Path = $Link; Directory = $directory })
    switch ($Kind) {
        Junction { $null = New-Item -ItemType Junction -Path $Link -Target $Target -ErrorAction Stop }
        DirectorySymbolicLink { $null = [IO.Directory]::CreateSymbolicLink($Link,$Target) }
        FileSymbolicLink { $null = [IO.File]::CreateSymbolicLink($Link,$Target) }
        HardLink { $null = New-Item -ItemType HardLink -Path $Link -Target $Target -ErrorAction Stop }
        default { throw 'Unknown fixture kind' }
    }
    $item = Get-Item -LiteralPath $Link -Force -ErrorAction Stop
    $attrs = [IO.File]::GetAttributes($Link)
    if ($Kind -eq 'HardLink') {
        if ($item.LinkType -ne 'HardLink' -or ($attrs -band [IO.FileAttributes]::ReparsePoint) -ne 0 -or (Get-Item -LiteralPath $Target -Force -ErrorAction Stop).LinkType -ne 'HardLink') { throw 'Hardlink fixture mismatch' }
    } else {
        $expected = if ($Kind -eq 'Junction') { 'Junction' } else { 'SymbolicLink' }
        if ($item.LinkType -ne $expected -or ($attrs -band [IO.FileAttributes]::ReparsePoint) -eq 0 -or [string](@($item.Target)[0]) -ne $Target) { throw "Alias fixture mismatch: $Kind" }
    }
}
function Assert-Metadata([string]$Case,[string]$Path,[bool]$Directory,[bool]$Reparse,[int]$Links = -1) {
    $actual = @(Get-DuplicateReportPathMetadata $Path)
    if ($actual.Count -ne 1 -or $null -eq $actual[0]) { throw "Metadata absent: $Case" }
    $attrs = [IO.FileAttributes]$actual[0].Attributes
    if ((($attrs -band [IO.FileAttributes]::Directory) -ne 0) -ne $Directory -or (($attrs -band [IO.FileAttributes]::ReparsePoint) -ne 0) -ne $Reparse) { throw "Metadata flags mismatch: $Case attributes=$attrs" }
    if ($Links -ge 0 -and [uint32]$actual[0].NumberOfLinks -ne [uint32]$Links) { throw "Metadata link count mismatch: $Case links=$($actual[0].NumberOfLinks)" }
    $script:passed++
    Write-Output "METADATA_PASS case=$Case attributes=$attrs links=$($actual[0].NumberOfLinks)"
}
function Assert-NotFound([string]$Case,[string]$Path) {
    $actual = Get-DuplicateReportPathMetadata $Path
    if ($null -ne $actual) { throw "Missing direct child was not absent: $Case" }
    $script:passed++
    Write-Output "METADATA_PASS case=$Case result=absent"
}
function Assert-PathFailure([string]$Case,[string]$Path) {
    $failure = $null
    try { $null = Get-DuplicateReportPathMetadata $Path } catch { $failure = $_.Exception }
    if ($null -eq $failure) { throw "Invalid parent did not fail closed: $Case" }
    $native = $failure
    while ($null -ne $native -and $native -isnot [ComponentModel.Win32Exception]) { $native = $native.InnerException }
    if ($null -eq $native -or $native.NativeErrorCode -notin @(3,267)) { throw "Unexpected invalid-parent error: $Case $failure" }
    $script:passed++
    Write-Output "METADATA_PASS case=$Case win32_error=$($native.NativeErrorCode)"
}
try {
    if (Test-Path -LiteralPath $scratch) { throw 'Scratch path already exists' }
    New-Item -ItemType Directory -Path $scratch -ErrorAction Stop | Out-Null
    $owned = $true
    $repo = Join-Path $scratch 'repo'
    $collector = Join-Path $repo 'project_sources/collector'
    $outside = Join-Path $scratch 'outside'
    $literal = Join-Path $collector 'literal [x]'
    $null = [IO.Directory]::CreateDirectory($literal)
    $null = [IO.Directory]::CreateDirectory($outside)
    $file = Join-Path $literal 'report name.json'
