    Write-Output "NATIVE_METADATA_CAPABILITY PWSH=$($PSVersionTable.PSVersion)"
    Assert-Metadata 'ordinary-directory' $collector $true $false
    Assert-Metadata 'literal-directory' $literal $true $false
    Assert-Metadata 'regular-file' $file $false $false 1
    Assert-NotFound 'missing-leaf' (Join-Path $collector 'missing.json')
    Assert-NotFound 'missing-directory-component' (Join-Path $collector 'missing-directory')
    Assert-PathFailure 'missing-parent' (Join-Path $collector 'missing-directory/report.json')
    Assert-PathFailure 'file-as-parent' (Join-Path $file 'report.json')
    $junction = Join-Path $collector 'junction'
    New-OwnedAlias Junction $junction $outside
    Assert-Metadata 'junction' $junction $true $true
    $dirLink = Join-Path $collector 'dir-link'
    New-OwnedAlias DirectorySymbolicLink $dirLink $outside
    Assert-Metadata 'directory-symlink' $dirLink $true $true
    $fileLink = Join-Path $collector 'file-link.json'
    New-OwnedAlias FileSymbolicLink $fileLink $sentinel
    Assert-Metadata 'file-symlink' $fileLink $false $true
    $dangling = Join-Path $collector 'dangling.json'
    New-OwnedAlias FileSymbolicLink $dangling $absent
    Assert-Metadata 'dangling-file-symlink' $dangling $false $true
    Assert-Metadata 'before-hardlink' $sentinel $false $false 1
    $hardLink = Join-Path $collector 'hardlink.json'
    New-OwnedAlias HardLink $hardLink $sentinel
    Assert-Metadata 'hardlink-leaf' $hardLink $false $false 2
    Assert-Metadata 'hardlink-target-count' $sentinel $false $false 2
    [IO.File]::Delete($hardLink)
    Assert-Metadata 'after-hardlink-removal' $sentinel $false $false 1
    if ([IO.File]::ReadAllText($file) -cne 'inside-sentinel' -or [IO.File]::ReadAllText($sentinel) -cne 'outside-sentinel' -or [IO.File]::Exists($absent) -or [IO.Directory]::Exists((Join-Path $collector 'missing-directory'))) { throw 'Owned fixture content or absence changed' }
    if ($passed -ne 15) { throw "Unexpected metadata count: $passed" }
    Write-Output "NATIVE_METADATA_CAPABILITY_COMPLETE passed=$passed"
} finally {
    Set-Location -LiteralPath $start
    if ($owned) {
        for ($index=$links.Count-1;$index -ge 0;$index--) {
            $entry = $links[$index]
            try { $attrs = [IO.File]::GetAttributes($entry.Path) }
            catch [IO.FileNotFoundException] { continue }
            catch [IO.DirectoryNotFoundException] { continue }
            if ($entry.Directory) {
                if (($attrs -band [IO.FileAttributes]::ReparsePoint) -eq 0) { throw 'Unverified directory alias; refusing recursive cleanup' }
                [IO.Directory]::Delete($entry.Path,$false)
            } else { [IO.File]::Delete($entry.Path) }
            try { $null = [IO.File]::GetAttributes($entry.Path); throw 'Alias cleanup failed' }
            catch [IO.FileNotFoundException] { }
            catch [IO.DirectoryNotFoundException] { }
        }
        Remove-Item -LiteralPath $scratch -Recurse -Force -ErrorAction Stop
    }
}
Write-Output 'NATIVE_METADATA_SCRATCH_CLEANUP_COMPLETE'

